"""Verify exact RNG order and pair the production training calls."""
import json
import statistics
import sys
from dataclasses import asdict
from pathlib import Path
from time import perf_counter_ns

import torch

from bio_inspired_nanochat import synaptic
from bio_inspired_nanochat.perf_regression import PerfRegressionHarness, STANDARD_BENCHMARK_CONFIGS
from rng_out import preallocated_rng


def bitwise_equal(a, b):
    return torch.equal(a.contiguous().view(torch.int32), b.contiguous().view(torch.int32))


def exact(kernels):
    passed = 0
    for batch, heads, queries, topk, attn_topk in (
        (1, 1, 1, 1, 1), (2, 4, 32, 32, 32), (2, 4, 31, 7, 32), (2, 2, 13, 5, 7),
    ):
        for mask in ("all", "some", "empty"):
            valid = torch.ones((batch, heads, queries, topk), dtype=torch.bool)
            if mask == "some":
                valid[0, 0, ::2, :] = False
                valid[..., -1] = True
                valid[0, 0, 0, :] = False
            elif mask == "empty":
                valid.fill_(False)
            for frac in (0.0, 0.12, 0.35, 1.0):
                for cap in (0, 8):
                    for private in (False, True):
                        values, states = [], []
                        for kernel in kernels.values():
                            torch.manual_seed(4419)
                            generator = torch.Generator().manual_seed(9931) if private else None
                            values.append(kernel(valid, generator, batch, heads, queries,
                                                 topk, attn_topk, frac, cap))
                            states.append((
                                torch.get_rng_state(),
                                None if generator is None else generator.get_state(),
                            ))
                        assert all(bitwise_equal(a, b) for a, b in zip(*values, strict=True))
                        assert torch.equal(states[0][0], states[1][0])
                        if private:
                            assert torch.equal(states[0][1], states[1][1])
                        passed += 1
    return passed


def timed_rng(kernels):
    rows = {"32": {}, "128": {}}
    for queries in (32, 128):
        valid = torch.ones((2, 4, queries, 32), dtype=torch.bool)
        samples = {phase: [] for phase in kernels}
        for rep in range(88):
            for phase in list(kernels)[::(-1 if rep % 2 else 1)]:
                generator = torch.Generator().manual_seed(7149 + rep)
                started = perf_counter_ns()
                uniform, noise = kernels[phase](valid, generator, 2, 4, queries, 32, 32, 0.12, 8)
                uniform.contiguous().numpy()
                noise.contiguous().numpy()
                duration = perf_counter_ns() - started
                if rep >= 8:
                    samples[phase].append(duration)
        rows[str(queries)] = samples
    return rows


def training(kernels):
    harness = PerfRegressionHarness()
    vanilla, bio = [cfg for cfg in STANDARD_BENCHMARK_CONFIGS if cfg.mode == "train"]
    original = synaptic._scripted_rust_scan_rng
    calls = dict.fromkeys(kernels, 0)
    rows = []

    def measured(seed, phase):
        torch.manual_seed(seed)
        if phase == "vanilla":
            return harness.run_benchmark(vanilla)

        def counted(*args, **kwargs):
            calls[phase] += 1
            return kernels[phase](*args, **kwargs)

        synaptic._scripted_rust_scan_rng = counted
        return harness.run_benchmark(bio)

    try:
        for phase in ("vanilla", *kernels):
            measured(24529, phase)
        for index, seed in enumerate(range(24530, 24542)):
            order = ["vanilla", *kernels][::(-1 if index % 2 else 1)]
            results = {phase: measured(seed, phase) for phase in order}
            comps = {
                phase: asdict(harness.evaluate_budget_gates([results["vanilla"], results[phase]])[0])
                for phase in kernels
            }
            rows.append({"seed": seed, "order": order, "results": comps})
    finally:
        synaptic._scripted_rust_scan_rng = original
    assert list(calls.values()) == [182, 182], calls
    return rows, calls


def main():
    kernels = {"baseline": synaptic._scripted_rust_scan_rng, "candidate": preallocated_rng}
    cases = exact(kernels)
    assert cases == 192, cases
    rows, count = training(kernels)
    rng_timings = timed_rng(kernels)
    summary = {
        "identical_cases": cases,
        "calls": count,
        "median_ratios": {
            phase: statistics.median(row["results"][phase]["slowdown_ratio"] for row in rows)
            for phase in kernels
        },
        "budget_passes": {
            phase: sum(row["results"][phase]["passed"] for row in rows)
            for phase in kernels
        },
        "median_paired_improvement": statistics.median(
            1.0 - row["results"]["candidate"]["slowdown_ratio"] / row["results"]["baseline"]["slowdown_ratio"]
            for row in rows
        ),
        "median_rng_ns": {
            name: {phase: statistics.median(samples) for phase, samples in arms.items()}
            for name, arms in rng_timings.items()
        },
    }
    with Path(sys.argv[1]).open("x", encoding="utf-8") as stream:
        json.dump({"summary": summary, "training": rows, "rng_timings": rng_timings},
                  stream, sort_keys=True, indent=2, allow_nan=False)
        stream.write("\n")
    print(json.dumps(summary, sort_keys=True))


if __name__ == "__main__":
    main()

