"""Alternate both exact native scan functions inside one CPU process."""
import importlib.util
import json
import statistics
import sys
from dataclasses import asdict
from pathlib import Path
from time import perf_counter_ns

import torch

from bio_inspired_nanochat import synaptic
from bio_inspired_nanochat.perf_regression import PerfRegressionHarness, STANDARD_BENCHMARK_CONFIGS
from masked_contract import make_case


def load_kernel(root, phase):
    elf, = (root / f"{phase}-site" / "rustbpe").glob("*.so")
    spec = importlib.util.spec_from_file_location(f"{phase}.rustbpe", elf)
    assert spec is not None and spec.loader is not None
    extension = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(extension)
    assert extension.PRESYN_CPU_ABI == 1 and Path(extension.__file__) == elf
    return extension.presyn_detached_scan_cpu


def time_kernels(kernels):
    results = {}
    for queries, mask in ((32, "causal"), (128, "causal"), (128, "full")):
        state, delay, args = make_case(queries=queries, mask=mask, stochastic=True)
        times = {phase: [] for phase in kernels}
        for rep in range(88):
            for phase in list(kernels)[::(-1 if rep % 2 else 1)]:
                step_state, step_delay = state.copy(), delay.copy()
                started = perf_counter_ns()
                out, grad = kernels[phase](step_state, step_delay, *args)
                elapsed = perf_counter_ns() - started
                assert out.shape == grad.shape == (8, queries, 32)
                if rep >= 8:
                    times[phase].append(elapsed)
        results[f"{queries}/{mask}"] = times
    return results


def time_training(kernels):
    harness = PerfRegressionHarness()
    vanilla, bio = [cfg for cfg in STANDARD_BENCHMARK_CONFIGS if cfg.mode == "train"]
    assert not vanilla.synaptic and bio.synaptic
    factory = synaptic._rust_detached_scan_kernel
    kernel_calls = {phase: 0 for phase in kernels}

    def instrumented_kernel(phase):
        def call(*args, **kwargs):
            kernel_calls[phase] += 1
            return kernels[phase](*args, **kwargs)
        return call

    dispatch = {phase: instrumented_kernel(phase) for phase in kernels}

    def benchmark(seed, phase):
        torch.manual_seed(seed)
        if phase == "vanilla":
            return harness.run_benchmark(vanilla)
        synaptic._rust_detached_scan_kernel = lambda: dispatch[phase]
        return harness.run_benchmark(bio)

    rows = []
    try:
        for phase in ("vanilla", *kernels):
            benchmark(24469, phase)
        for rep, seed in enumerate(range(24470, 24482)):
            order = ["vanilla", *kernels][::(-1 if rep % 2 else 1)]
            results = {phase: benchmark(seed, phase) for phase in order}
            comparisons = {
                phase: asdict(harness.evaluate_budget_gates([results["vanilla"], results[phase]])[0])
                for phase in kernels
            }
            rows.append({"seed": seed, "order": order, "results": comparisons})
    finally:
        synaptic._rust_detached_scan_kernel = factory
    assert list(kernel_calls.values()) == [182, 182], kernel_calls  # 13 x 7 x 2 layers
    return rows, kernel_calls


def main():
    root, output = map(Path, sys.argv[1:])
    baseline = synaptic.rust_presyn_cpu_backend()
    assert baseline is not None and Path(baseline.__file__).is_relative_to(root / "baseline-site")
    kernels = {
        "baseline": baseline.presyn_detached_scan_cpu,
        "candidate": load_kernel(root, "candidate"),
    }
    train, calls = time_training(kernels)
    native = time_kernels(kernels)
    summary = {
        "train_pairs": len(train),
        "kernel_calls": calls,
        "median_ratios": {
            phase: statistics.median(row["results"][phase]["slowdown_ratio"] for row in train)
            for phase in kernels
        },
        "median_paired_improvement": statistics.median(
            1.0 - row["results"]["candidate"]["slowdown_ratio"] / row["results"]["baseline"]["slowdown_ratio"]
            for row in train
        ),
        "native_medians_ns": {
            name: {phase: statistics.median(samples) for phase, samples in arms.items()}
            for name, arms in native.items()
        },
    }
    with output.open("x", encoding="utf-8") as stream:
        json.dump({"training": train, "native": native, "summary": summary}, stream,
                  sort_keys=True, indent=2, allow_nan=False)
        stream.write("\n")
    print(json.dumps(summary, sort_keys=True))


if __name__ == "__main__":
    main()

